dst=parent/"data"
out={"project":"pink-iptv","status":"BLOCKED","changed":False}
created=False;moved=False
def states():
 return {n:subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=7).stdout.strip() for n in ("ssh","nginx","pink-vpn","pink-iptv-backend","lowcost-europa","fadego-staging","pm2-root","pm2-iptvpn-bot")}
try:
 if not src.is_dir() or src.is_symlink() or not root.is_dir() or root.is_symlink() or dst.exists() or dst.is_symlink():raise RuntimeError("real_source_or_canonical_target_invalid")
 stat=src.stat()
 if stat.st_dev!=root.stat().st_dev or stat.st_uid!=0 or stat.st_mode&0o777!=0o700:raise RuntimeError("source_identity_or_filesystem_mismatch")
 if parent.exists() and (not parent.is_dir() or parent.is_symlink()):raise RuntimeError("vpn_parent_invalid")
 contents=[p for p in src.iterdir()]
 if len(contents)!=1 or not contents[0].is_file() or contents[0].is_symlink():raise RuntimeError("unexpected_state_layout")
 h=hashlib.sha256(contents[0].read_bytes()).digest()
 baseline=states()
 if baseline["pink-vpn"]!="active":raise RuntimeError("vpn_service_not_active")
 if not parent.exists():
  parent.mkdir(mode=0o750);created=True
  os.chown(parent,0,root.stat().st_gid)
 os.rename(src,dst);moved=True
 os.symlink(str(dst),src)
 after=dst.stat()
 if not src.is_symlink() or src.resolve(strict=True)!=dst or dst.is_symlink() or (stat.st_dev,stat.st_ino,stat.st_uid,stat.st_gid,stat.st_mode&0o777)!=(after.st_dev,after.st_ino,after.st_uid,after.st_gid,after.st_mode&0o777):raise RuntimeError("directory_identity_changed")
 now=list(dst.iterdir())
 if len(now)!=1 or hashlib.sha256(now[0].read_bytes()).digest()!=h:raise RuntimeError("state_file_hash_changed")
 if states()!=baseline:raise RuntimeError("protected_services_state_changed")
 out.update(status="MOVED_VERIFIED",changed=True,physical_root=str(dst),legacy_alias=str(src),state_file_sha256_preserved=True,uid_gid_permissions_inode_preserved=True,services_unchanged=True,active_vpn_unchanged=True)
except Exception as e:
 out["reason"]=str(e)[:155]
 if src.is_symlink() and src.resolve(strict=False)==dst:src.unlink()
 if moved and dst.is_dir() and not src.exists() and not src.is_symlink():
  try:os.rename(dst,src);out["rollback"]="RESTORED"
  except Exception:out["rollback"]="INCOMPLETE"
 if created and parent.is_dir() and not list(parent.iterdir()):parent.rmdir()
print(json.dumps(out,sort_keys=True))
if out["status"]!="MOVED_VERIFIED":raise SystemExit(3)
